const packages = $input.first().json;
const packageList = Array.isArray(packages) ? packages : Object.keys(packages);
const results = [];
for (const pkgName of packageList) {
  try {
    const response = await $http.request({ method: 'GET', url: `https://registry.npmjs.org/${pkgName}`, json: true });
    const latest = response['dist-tags']?.latest;
    const versions = Object.keys(response.versions || {});
    const stableVersions = versions.filter(v => !v.includes('-'));
    const latestIndex = stableVersions.indexOf(latest);
    const previousVersion = latestIndex > 0 ? stableVersions[latestIndex - 1] : null;
    const latestMajor = latest ? parseInt(latest.split('.')[0], 10) : 0;
    const prevMajor = previousVersion ? parseInt(previousVersion.split('.')[0], 10) : 0;
    const isBreaking = latestMajor > prevMajor;
    results.push({ json: { package: pkgName, latestVersion: latest, previousVersion, latestMajor, prevMajor, isBreaking, npmUrl: `https://www.npmjs.com/package/${pkgName}` } });
  } catch (err) {
    results.push({ json: { package: pkgName, error: err.message, isBreaking: false } });
  }
}
return results;
